  "storageNotice.line": "Ces motifs ne sont gardés que dans ce navigateur, et un plantage ou une mise à jour du navigateur peut les effacer. « {button} » les enregistre tous dans un seul fichier.",
  "welcome.hide": "Masquer le guide de bienvenue - un lien dans le pied de page le fait revenir",
