  "shortcuts.group.help": "Aide",
  "shortcuts.commandSearch": "Ouvrez la recherche de commande",
  "interactiveHelp.title": "Aide interactive",
  "interactiveHelp.subtitle": "Cliquez sur un élément pour en savoir plus",
  "interactiveHelp.named": "« {name} »",
