  "cookieCutter.cancel": "Fermer l'emporte-pièce",
  "cookieCutter.help": "Le contour de la sélection devient une paroi fine avec un tranchant et un rebord plat autour de son pied. Ses trous, comme l'intérieur d'un e, reçoivent leurs propres parois. Paroi, hauteur et rebord se modifient ensuite dans les Propriétés.",
