  "shell.edgesHint": "S'applique là où les murs intérieurs s'écartent, au niveau d'une marche ou d'une ouverture. Les coins d'une boîte simple restent pointus à l'intérieur - arrondissez d'abord ses bords extérieurs pour obtenir un intérieur arrondi.",
