  "edge.revertOffset": "Décalage ({size} mm)",
  "historyStep.offsetOne": "{name} décalé",
  "historyStep.offsetMany": "{count} objets décalés",
  "guide.edges.offset": "Le décalage déplace chaque face d'un corps de la même distance, vers l'extérieur ou l'intérieur. Agrandis une copie et garde-la comme trou pour obtenir le jeu d'un ajustement, ou réduis un corps pour un tenon qui doit entrer dans un trou. Les corps qui ne sont qu'un maillage de triangles ne peuvent souvent pas être décalés.",
  "edge.revertSurfaceTexture": "Texture de surface ({size} mm de profondeur)",
  "deleteFace.title": "Supprimer une face",
  "deleteFace.subtitle": "Les faces autour referment le vide",
  "deleteFace.help": "Cliquez sur les faces à supprimer ; un nouveau clic retire une face de la sélection. Les faces autour s'étendent jusqu'à refermer le vide : un congé, un trou ou un bossage disparaît, et le corps reste exact.",
  "deleteFace.preparing": "Lecture des faces…",
