  "thread.flankAngleHint": "L'angle entre les deux flancs d'une dent. 60° est le filetage en V pointu, 30° le filetage trapézoïdal. À 90° ou moins, aucun flanc n'est plus plat que 45°, le fil s'imprime donc sans support.",
  "prop.clearance": "Dégagement (XY)",
  "prop.threadChamferTop": "Chanfrein, extrémité supérieure",
  "prop.threadChamferBottom": "Chanfrein, extrémité inférieure",
  "thread.axialClearanceHint": "Jeu supplémentaire le long du filetage, en mm, en plus du jeu : chaque dent de l'écrou devient d'autant plus fine tandis que le diamètre reste. Pour un filetage lâche qui ne vibre pas latéralement : gardez le jeu entre 0,2 et 0,3 et réglez ici 0,2. A 0, le jeu vient uniquement du dégagement, qui ouvre les flancs seulement environ la moitié.",
  "thread.clearanceHint": "L'espace supplémentaire sur tout le diamètre. Un fil imprimé a besoin de plus que vous ne le pensez : l'espace entre les flancs n'en représente qu'environ la moitié. Environ 0,3 est serré, 0,4 habituel, 0,5 lâche. Imprimez d'abord une paire de test.",
  "thread.boltClearanceHint": "Rend le boulon plus fin d'autant, pour un écrou métallique qui n'a pas de jeu propre (0,3 à 0,4, autant qu'un écrou imprimé l'aurait fait). Avec un écrou imprimé, laissez-le à 0 et donnez de la place à l'écrou.",
