  "prop.hingeScrewAcrossHint": "Du trou d'une feuille au trou de l'autre, de centre à centre. 0 place chaque trou au milieu de sa feuille.",
  "prop.gridfinityType": "Type",
  "gridfinity.bin": "Bac",
  "gridfinity.baseplate": "Socle",
  "gridfinity.binHint": "Un bac sur la grille Gridfinity de 42 mm : il se pose dans un socle et s'empile sur d'autres bacs, y compris ceux d'autres générateurs Gridfinity.",
  "gridfinity.baseplateHint": "Le support dans lequel se posent les bacs Gridfinity, 5 mm de haut : un logement pour chaque unité de grille de 42 mm.",
  "gridfinity.tray": "Barquette",
  "gridfinity.trayHint": "Une barquette de n'importe quelle taille en mm à fond plat, pour les inserts de jeux de société et les petites pièces : sans pieds ni rebord d'empilage, elle ne se pose donc pas dans un socle et ne s'empile pas. Ses cloisons et ses tablettes d'étiquette montent jusqu'en haut.",
  "prop.gridfinityUnitsX": "Unités en largeur",
  "prop.gridfinityUnitsZ": "Unités en profondeur",
  "prop.gridfinityUnitsY": "Unités de hauteur",
  "prop.gridfinityLip": "Rebord d'empilage",
  "prop.gridfinityLipChamfer": "Chanfrein du rebord",
  "gridfinity.lipChamferHint": "Chanfreine l'arête supérieure du rebord d'empilage ; à 0, elle reste vive, comme la spécification Gridfinity la dessine.",
  "prop.gridfinityMagnets": "Trous pour aimants",
  "prop.gridfinityHalfGrid": "Demi-grille (21 mm)",
  "gridfinity.halfGridHint": "Les unités en largeur et en profondeur comptent des cellules de 21 mm, chacune avec son propre pied ; quatre se posent dans un logement du socle.",
  "prop.gridfinityFloorHeight": "Hauteur du fond",
  "gridfinity.floorHeightHint": "Jusqu'à cette hauteur, mesurée depuis le dessous, le bac est plein : une ébauche dans laquelle découper des formes.",
  "prop.gridfinityWallThickness": "Épaisseur de paroi",
  "gridfinity.wallThicknessHint": "La paroi est mesurée depuis l'extérieur, qui ne change pas. Avec le rebord d'empilage, une paroi de plus de 1,75 mm s'arrête à un palier 0,85 mm sous 7 mm par unité de hauteur, sans toucher les pieds d'un bac empilé dessus.",
